package com.example.javaanalyzer.generation;

import com.example.javaanalyzer.ir.MapperModel;
import com.example.javaanalyzer.ir.MapperStatementModel;
import com.example.javaanalyzer.ir.MethodModel;
import com.example.javaanalyzer.ir.ProjectModel;
import com.example.javaanalyzer.ir.StatementSource;
import com.example.javaanalyzer.ir.TypeModel;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;

/**
 * The MyBatis screen (FR-15, SCR-08). SQL is shown as written; {@code <include>} is not expanded
 * and methods generated by a base mapper such as {@code BaseMapper} are not listed.
 */
public final class MyBatisReportGenerator {

  public static final String INCLUDE_NOTE = "<include> は展開せず、記述どおりに表示する。SQL の意味解析はしない。";

  static final String NO_SQL = "SQL なし";

  private MyBatisReportGenerator() {}

  /** Mappers that have an interface, sorted by its name. */
  public static List<MapperReport> mappers(ProjectModel model) {
    return model.mappers().stream()
        .filter(mapper -> mapper.interfaceType() != null)
        .sorted(Comparator.comparing(MapperModel::interfaceType))
        .map(mapper -> report(model, mapper))
        .toList();
  }

  /** XML namespaces that no interface matches, sorted by namespace. */
  public static List<MapperReport> namespacesWithoutInterface(ProjectModel model) {
    return model.mappers().stream()
        .filter(mapper -> mapper.interfaceType() == null)
        .sorted(Comparator.comparing(m -> Labels.orDash(m.namespace())))
        .map(mapper -> report(model, mapper))
        .toList();
  }

  /** Every statement of every mapper, for the exports. */
  public static Table statementTable(ProjectModel model) {
    List<MapperModel> mappers = new ArrayList<>();
    mappers.addAll(
        model.mappers().stream()
            .filter(m -> m.interfaceType() != null)
            .sorted(Comparator.comparing(MapperModel::interfaceType))
            .toList());
    mappers.addAll(
        model.mappers().stream()
            .filter(m -> m.interfaceType() == null)
            .sorted(Comparator.comparing(m -> Labels.orDash(m.namespace())))
            .toList());
    List<List<Cell>> rows = new ArrayList<>();
    for (MapperModel mapper : mappers) {
      for (MapperStatementModel statement : mapper.statements()) {
        rows.add(
            List.of(
                Cell.typeName(mapper.interfaceType()),
                Cell.of(Labels.orDash(mapper.namespace())),
                Cell.of(statement.tag()),
                Cell.of(statement.id()),
                Cell.of(source(statement.source())),
                Cell.of(Labels.orDash(statement.methodName())),
                Cell.of(
                    statement.sqlResolved()
                        ? statement.sql()
                        : statement.sql() + Labels.UNRESOLVED_SUFFIX)));
      }
    }
    return new Table(List.of("Mapper", "namespace", "タグ", "id", "種別", "対応メソッド", "SQL"), rows);
  }

  private static MapperReport report(ProjectModel model, MapperModel mapper) {
    List<KeyValue> information = new ArrayList<>();
    information.add(KeyValue.of("namespace", Labels.orDash(mapper.namespace())));
    information.add(KeyValue.of("XML ファイル", Labels.join(mapper.xmlFiles())));
    List<String> notes = new ArrayList<>();
    Table methods = null;
    if (mapper.interfaceType() != null) {
      information.add(new KeyValue("基底インタフェース", Cell.type(mapper.baseType())));
      if (mapper.baseType() != null) {
        notes.add("基底インタフェースの自動生成メソッドは表示しない。");
      }
      methods = methodTable(model, mapper);
    }
    String title =
        mapper.interfaceType() != null
            ? Labels.simpleName(mapper.interfaceType())
            : Labels.orDash(mapper.namespace());
    List<StatementReport> statements =
        mapper.statements().stream().map(MyBatisReportGenerator::statement).toList();
    return new MapperReport(mapper.interfaceType(), title, information, notes, methods, statements);
  }

  private static Table methodTable(ProjectModel model, MapperModel mapper) {
    Optional<TypeModel> type =
        model.types().stream()
            .filter(t -> t.qualifiedName().equals(mapper.interfaceType()))
            .findFirst();
    List<List<Cell>> rows = new ArrayList<>();
    for (MethodModel method : type.map(TypeModel::methods).orElse(List.of())) {
      String sql =
          mapper.statements().stream()
              .filter(s -> method.name().equals(s.methodName()))
              .map(s -> s.tag() + " " + s.id())
              .reduce((a, b) -> a + ", " + b)
              .orElse(NO_SQL);
      rows.add(
          List.of(
              Cell.of(method.name()),
              Cell.of(
                  Labels.join(
                      method.parameters().stream()
                          .map(p -> p.type().text() + " " + p.name())
                          .toList())),
              Cell.type(method.returnType()),
              Cell.of(sql)));
    }
    return new Table(List.of("メソッド", "引数", "戻り値", "SQL"), rows);
  }

  private static StatementReport statement(MapperStatementModel statement) {
    List<String> notes = new ArrayList<>();
    if (statement.methodName() == null) {
      notes.add("対応メソッドなし");
    }
    if (!statement.sqlResolved()) {
      notes.add("未解決（式のまま表示）");
    }
    return new StatementReport(
        statement.tag() + " " + statement.id() + "（" + source(statement.source()) + "）",
        statement.sql(),
        notes);
  }

  private static String source(StatementSource source) {
    return source == StatementSource.XML ? "XML" : "注解";
  }
}
